(16, 'mod_footer', 'mod footer', '', '', '<p>C&ocirc;ng ty TNHH Thương Mại Dịch Vụ Kỹ Thuật To&agrave;n Danh |</p>\n\n<p>Địa chỉ: 59/34/1 Đường số 8, P.Trường Thọ, Q.Thủ Đức, TP.HCM</p>\n\n<p>Xưởng lắp đặt: 21- Ph&uacute; Ch&acirc;u, P.Tam Ph&uacute;, Q.Thủ Đức, TP.HCM</p>\n\n<p>Điện thoại / Fax: 08.37205567 | Hotline : 0915760769</p>\n\n<p>Email: lethanh.pho@toandanhco.com.vn, info@toandanhco.com.vn</p>\n\n<p>&copy; 2015 Bản quyền thuộc về Toan Danh Co,.Ltd</p>\n', NULL, 1, '1', 746, 1, '2011-05-10', '0000-00-00'),
(32, 'mod_support', 'mod-support', '', '', '[removed][removed]\n<div id=\"SkypeButton_Call_thanhphole_1\">\n  [removed]\n    Skype.ui({\n      \"name\": \"chat\",\n      \"element\": \"SkypeButton_Call_thanhphole_1\",\n      \"participants\": [\"thanhphole\"],\n      \"imageSize\": 32\n    });\n  [removed]\n</div></p>\n\n<p style=\"text-align: center;\"><span style=\"font-size: 10pt;\">Hỗ trợ trực tuyến</span></p>\n\n<p style=\"text-align: center;\"><span style=\"font-size: 10pt; color: #ff0000;\">0915 760 769</span></p>', NULL, 1, '1', 748, 1, '2014-01-11', '0000-00-00'),
(31, 'mod_doi_tac', 'mod doi tac', '', '', '<marquee direction=\"up\">\n<ul id=\"slider164\" style=\"position: relative;height: 450px;\">\n <li style=\"width: 150px; height: 50px;\"><a href=\"#\" target=\"_blank\"><img alt=\"Mitsubishi\" src=\"https://toandanhco.com.vn/fileman/Uploads/Images/Logo-3.jpg\" style=\"height: 55px; width: 150px;\" /> </a></li>\n <li style=\"width: 150px; height: 70px;\"><a href=\"#\" target=\"_blank\"><img alt=\"Invt\" src=\"https://toandanhco.com.vn/fileman/Uploads/Images/logo-2.jpg\" style=\"height: 75px; width: 150px;margin-bottom:5px;\" /> </a></li>\n <li style=\"width: 140px; height: 80px;padding-top:10px;\"><a href=\"#\" target=\"_blank\"><img alt=\"LS\" src=\"https://toandanhco.com.vn/fileman/Uploads/Images/eaton-logo-small.png\" style=\"height: 51px; width: 140px; margin-top: 10px;\" /> ​</a></li>\n <li style=\"width: 150px; height: 50px;\"><a href=\"#\" target=\"_blank\"><img alt=\"LS\" src=\"https://toandanhco.com.vn/fileman/Uploads/Images/ROBBEN.png\" style=\"height: 51px; width: 150px;\" /> ​</a></li>\n <li style=\"width: 150px; height: 80px;\"><a href=\"#\" target=\"_blank\"><img alt=\"LS\" src=\"https://toandanhco.com.vn/fileman/Uploads/Images/ls.jpeg\" style=\"height: 83px; width: 150px;\" /> ​</a></li>\n <li style=\"width: 150px; height: 80px;\"><a href=\"#\" target=\"_blank\"><img alt=\"LS\" src=\"https://toandanhco.com.vn/fileman/Uploads/Images/erico.gif\" style=\"height: 83px; width: 150px;\" /> ​</a></li>\n</ul>\n</marquee>', NULL, 1, '1', 748, 1, '2013-08-21', '0000-00-00'),
(33, 'mod_contact_us', 'Mod contact us', '', '', '<p><span id=\"docs-internal-guid-ce295bc5-5c9c-8111-97be-ef7b73b2986f\"><span style=\"font-size: 15px; font-family: Arial; color: rgb(0, 0, 0); font-weight: bold; vertical-align: baseline; white-space: pre-wrap; background-color: transparent;\">C&Ocirc;NG TY TNHH THƯƠNG MẠI DỊCH VỤ KỸ THUẬT TO&Agrave;N DANH</span></span></p>\n\n<p>Địa chỉ:&nbsp;Địa chỉ: 59/34/1 Đường số 8, P.Trường Thọ, Q.Thủ Đức, TP.HCM</p>\n\n<p><span style=\"line-height: 20.7999992370605px;\">Xưởng lắp đặt:&nbsp;59/58E Đường số́ 8, P.Trường Thọ, Thủ Đức, HCM</span></p>\n\n<p>Điện thoại/Fax : 08. 37205567</p>\n\n<p>Hotline : 091.5760.769</p>\n\n<p>Email: lethanh.pho@toandanhco.com.vn,&nbsp;<span style=\"line-height: 20.8px;\">info@toandanhco.com.vn</span></p>\n\n<p>Website:&nbsp;https://www.toandanhco.com.vn</p>\n', NULL, 1, '1', 748, 1, '2015-01-09', '0000-00-00'),
(34, 'mod-left', 'mod-left', '', '', '<div class=\"module\"><img alt=\"advert\" class=\"img-rounded\" src=\"images/advert.png\" style=\"margin:20px 0;\" /> <img alt=\"advert\" class=\"img-rounded\" src=\"images/advert.png\" /></div>\n', NULL, 1, '2<di', 748, NULL, '2015-01-09', NULL);
INSERT INTO `toandanh_tnews` (`nid`, `nid_section_news`, `nid_cat_news`, `ccode`, `ctitle`, `cauthor`, `ctag`, `nhit`, `nimg`, `alwcmt`, `cdescription`, `cshort_content`, `ccontent`, `cimage_height`, `cimage_thumb`, `cimage_fb`, `cimage_iphone`, `nactive`, `nstatus`, `cindex`, `niduser01`, `niduser02`, `ddate01`, `ddate02`, `clink`, `cpost_date`, `cproduct_str_id`) VALUES
(491, 6, 5, 'dich-vu-bien-tan', 'Dịch vụ biến tần', '', '', NULL, '0', '0', '', '<p><span style=\"font-family: Arial, Helvetica, sans-serif; font-size: 13px; line-height: 24.7000007629395px; text-align: justify; background-color: rgb(255, 255, 255);\">Với đội ngũ kỹ thuật chuy&ecirc;n s&acirc;u, gi&agrave;u kinh nghiệm, c&ugrave;ng với những phần mềm hữu &iacute;ch từ h&atilde;ng, ch&uacute;ng t&ocirc;i sẽ gi&uacute;p kh&aacute;ch h&agrave;ng chọn lựa biến tần ph&ugrave; hợp, đ&aacute;p ứng y&ecirc;u cầu ứng dụng cụ thể của kh&aacute;ch h&agrave;ng trong khi vẫn đảm bảo ng&acirc;n s&aacute;ch cũng như&nbsp; tu&acirc;n thủ c&aacute;c y&ecirc;u cầu về tương th&iacute;ch điện từ v&agrave; s&oacute;ng h&agrave;i.</span></p>\n', '<div align=\"center\" style=\"color: rgb(0, 0, 0); font-family: Verdana, Arial, Helvetica, sans-serif; font-size: 12.8000001907349px; line-height: 17.9200000762939px;\">\n<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; text-align: center; background: rgb(255, 255, 255);\"><span style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 12pt; vertical-align: baseline; color: rgb(0, 0, 255); font-family: tahoma, arial, helvetica, sans-serif; background: transparent;\"><strong style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">DỊCH VỤ BIẾN TẦN</strong></span></p>\n\n<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; text-align: center; background: rgb(255, 255, 255);\"><strong style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">&nbsp;</strong></p>\n\n<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; text-align: center; background: rgb(255, 255, 255);\"><strong style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\"><img alt=\"Dich vu bien tan\" height=\"314\" src=\"https://www.dasautomation.vn/images/stories/virtuemart/product/Dich_vu_bien_tan.jpg\" style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\" width=\"450\" /></strong></p>\n\n<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; text-align: center; background: rgb(255, 255, 255);\"><img alt=\"Dich vu bien tan 1\" height=\"496\" src=\"https://www.dasautomation.vn/images/stories/virtuemart/product/Dich_vu_bien_tan_1.jpg\" style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\" width=\"450\" /></p>\n\n<ul>\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; background: rgb(255, 255, 255);\"><strong style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\"><span style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 255); background: transparent;\">Tư vấn chọn biến tần</span></strong></li>\n</ul>\n\n<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; text-align: justify; background: rgb(255, 255, 255);\">Với đội ngũ kỹ thuật chuy&ecirc;n s&acirc;u, gi&agrave;u kinh nghiệm, c&ugrave;ng với những phần mềm hữu &iacute;ch từ h&atilde;ng, ch&uacute;ng t&ocirc;i sẽ gi&uacute;p kh&aacute;ch h&agrave;ng chọn lựa biến tần ph&ugrave; hợp, đ&aacute;p ứng y&ecirc;u cầu ứng dụng cụ thể của kh&aacute;ch h&agrave;ng trong khi vẫn đảm bảo ng&acirc;n s&aacute;ch cũng như&nbsp; tu&acirc;n thủ c&aacute;c y&ecirc;u cầu về tương th&iacute;ch điện từ v&agrave; s&oacute;ng h&agrave;i.</p>\n\n<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; text-align: justify; background: rgb(255, 255, 255);\">&nbsp;</p>\n\n<ul>\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; background: rgb(255, 255, 255);\"><strong style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\"><span style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 255); background: transparent;\">Lắp đặt v&agrave; vận h&agrave;nh</span></strong></li>\n</ul>\n\n<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; text-align: justify; background: rgb(255, 255, 255);\">Tất cả c&aacute;c biến tần đều được thiết kế để dễ d&agrave;ng lắp đặt v&agrave; đưa v&agrave;o sử dụng, thiết kế dạng m&ocirc; đun dễ th&aacute;o lắp, m&agrave;n h&igrave;nh rời. Tất cả gi&uacute;p tiết kiệm chi ph&iacute; v&agrave; thời gian cho việc lắp đặt v&agrave; đưa v&agrave;o sử dụng cũng như bảo tr&igrave;. Ch&uacute;ng t&ocirc;i cung cấp, hướng dẫn về&nbsp; phần mềm phục vụ cho việc c&agrave;i đặt, đưa biến tần v&agrave;o sử dụng cũng như chẩn đo&aacute;n lỗi.</p>\n\n<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; text-align: justify; background: rgb(255, 255, 255);\">&nbsp;</p>\n\n<ul>\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; background: rgb(255, 255, 255);\"><strong style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\"><span style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 255); background: transparent;\">Bảo tr&igrave;</span></strong></li>\n</ul>\n\n<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; text-align: justify; background: rgb(255, 255, 255);\">Ch&uacute;ng t&ocirc;i thực hiện c&aacute;c khảo s&aacute;t thực tế tại nh&agrave; m&aacute;y của kh&aacute;ch h&agrave;ng, lấy cơ sở cho việc l&ecirc;n kế hoạch n&acirc;ng cấp v&agrave; bảo tr&igrave; biến tần d&agrave;i hạn. Việc khảo s&aacute;t gi&uacute;p x&aacute;c định c&aacute;c phương &aacute;n thực hiện nhằm giảm chi ph&iacute; vận h&agrave;nh, cải thiện năng suất, tăng độ tin cậy của hệ thống. Sau đ&oacute; ch&uacute;ng t&ocirc;i sẽ cung cấp lịch tr&igrave;nh bảo tr&igrave; ph&ograve;ng ngừa cho biến tần của kh&aacute;ch h&agrave;ng.</p>\n\n<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; text-align: justify; background: rgb(255, 255, 255);\">&nbsp;</p>\n\n<ul>\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; background: rgb(255, 255, 255);\"><strong style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\"><span style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 255); background: transparent;\">N&acirc;ng cấp, cải tạo v&agrave; thay thế</span></strong></li>\n</ul>\n\n<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; text-align: justify; background: rgb(255, 255, 255);\">C&aacute;c n&acirc;ng cấp biến tần được thiết kế nhằm cải thiện hoạt động v&agrave; k&eacute;o d&agrave;i tuổi thọ lẫn chức năng của biến tần để kh&aacute;ch h&agrave;ng c&oacute; thể thu hồi vốn đầu tư một c&aacute;ch nhanh nhất. Ch&uacute;ng t&ocirc;i cung cấp c&aacute;c dịch vụ cập nhật phần cứng v&agrave; phần mềm biến tần cũng như tư vấn về t&iacute;nh khả thi của việc n&acirc;ng cấp, những lợi &iacute;ch của việc n&acirc;ng cấp biến tần mang lại.</p>\n</div>\n', '', 'Dich_vu_bien_tan_20150515054855.jpg.webp', '', '', 1, 0, '', 748, 1, '2015-01-08', '2015-05-15', NULL, NULL, NULL),
(493, 6, 5, 'tiet-kiem-nang-lu', 'Tiết kiệm năng lượng', '', '', NULL, '0', '0', '', '<p><span style=\"font-family: Arial, Helvetica, sans-serif; font-size: 13px; line-height: 24.7000007629395px; background-color: rgb(255, 255, 255);\">&nbsp; Tiết kiệm năng lượng l&agrave; một ti&ecirc;u ch&iacute; quan trọng m&agrave; c&aacute;c tổ chức, doanh nghiệp đ&atilde; v&agrave; đang hướng tới. Tr&ecirc;n thực tế, hầu hết c&aacute;c tổ chức, doanh nghiệp đều xảy ra t&igrave;nh trạng l&atilde;ng ph&iacute; năng lượng ở một số bộ phận hoặc tr&ecirc;n diện rộng do sử dụng c&ocirc;ng nghệ lạc hậu, thiết kế chưa tối ưu, vận h&agrave;nh chưa ph&ugrave; hợp, h&agrave;nh vi sử dụng chưa hiệu quả,&hellip; kết quả của những giải ph&aacute;p tiết kiệm năng lượng &aacute;p dụng thường mang lại hiệu quả tiết kiệm năng lượng từ 5% đến 40% năng lượng ti&ecirc;u thụ.</span></p>\n', '<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; text-align: center; background: rgb(255, 255, 255);\"><span style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 12pt; vertical-align: baseline; font-family: tahoma, arial, helvetica, sans-serif; color: rgb(0, 0, 255); background: transparent;\"><strong style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">TIẾT KIỆM NĂNG LƯỢNG</strong></span></p>\n\n<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; text-align: center; background: rgb(255, 255, 255);\"><br data-mce-bogus=\"1\" />\n<img alt=\"Tiet kiem nang luong 1\" height=\"320\" src=\"https://www.dasautomation.vn/images/images/Tiet_kiem_nang_luong_1.jpg\" style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\" width=\"400\" /></p>\n\n<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; background: rgb(255, 255, 255);\">&nbsp; &nbsp; &nbsp; &nbsp; Tiết kiệm năng lượng l&agrave; một ti&ecirc;u ch&iacute; quan trọng m&agrave; c&aacute;c tổ chức, doanh nghiệp đ&atilde; v&agrave; đang hướng tới. Tr&ecirc;n thực tế, hầu hết c&aacute;c tổ chức, doanh nghiệp đều xảy ra t&igrave;nh trạng l&atilde;ng ph&iacute; năng lượng ở một số bộ phận hoặc tr&ecirc;n diện rộng do sử dụng c&ocirc;ng nghệ lạc hậu, thiết kế chưa tối ưu, vận h&agrave;nh chưa ph&ugrave; hợp, h&agrave;nh vi sử dụng chưa hiệu quả,&hellip; kết quả của những giải ph&aacute;p tiết kiệm năng lượng &aacute;p dụng thường mang lại hiệu quả tiết kiệm năng lượng từ 5% đến 40% năng lượng ti&ecirc;u thụ.</p>\n\n<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; background: rgb(255, 255, 255);\">&nbsp; &nbsp; &nbsp; &nbsp; Sử dụng năng lượng hiệu quả l&agrave; g&oacute;p phần t&iacute;ch cực v&agrave;o việc giảm bớt c&aacute;c chi ph&iacute; v&agrave; rủi ro, gia tăng lợi nhuận cho doanh nghiệp, đồng thời g&oacute;p phần bảo vệ m&ocirc;i trường một c&aacute;ch t&iacute;ch cực.<br />\n&nbsp; &nbsp; &nbsp; &nbsp; C&ocirc;ng ty TNHH Tự động h&oacute;a DAS l&agrave; nh&agrave; tư vấn, cung cấp c&aacute;c giải ph&aacute;p sử dụng năng lượng hiệu quả, sẽ l&agrave; đối t&aacute;c tin cậy, đồng h&agrave;nh c&ugrave;ng kh&aacute;ch h&agrave;ng tr&ecirc;n con đường n&acirc;ng cao hiệu quả sử dụng năng lượng. Ch&uacute;ng t&ocirc;i cung cấp cho Qu&yacute; kh&aacute;ch h&agrave;ng:</p>\n\n<ul style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; list-style: none; clear: both; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; background: rgb(255, 255, 255);\">\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; line-height: 1.9; list-style-position: outside; background: transparent;\"><span style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 255); background: transparent;\">&nbsp; &nbsp; &nbsp;&nbsp;- Tư vấn giải ph&aacute;p v&agrave; kiểm to&aacute;n năng lượng</span></li>\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; line-height: 1.9; list-style-position: outside; background: transparent;\"><span style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 255); background: transparent;\">&nbsp; &nbsp; &nbsp; - Cung cấp thiết bị tiết kiệm năng lượng</span></li>\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; line-height: 1.9; list-style-position: outside; background: transparent;\"><span style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 255); background: transparent;\">&nbsp; &nbsp; &nbsp; - Thực hiện c&aacute;c giải ph&aacute;p tiết kiệm năng lượng</span></li>\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; line-height: 1.9; list-style-position: outside; background: transparent;\"><span style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 255); background: transparent;\">&nbsp; &nbsp; &nbsp; - Đo lường, gi&aacute;m s&aacute;t v&agrave; cải tiến</span></li>\n</ul>\n\n<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; background: rgb(255, 255, 255);\">&nbsp; &nbsp; &nbsp; &nbsp; Với hợp đồng tư vấn, kiểm to&aacute;n năng lượng, ch&uacute;ng t&ocirc;i sẽ hỗ trợ kh&aacute;ch h&agrave;ng nhanh ch&oacute;ng &aacute;p dụng c&aacute;c giải ph&aacute;p sử dụng năng lượng hiệu quả, th&ocirc;ng qua việc gi&uacute;p kh&aacute;ch h&agrave;ng:</p>\n\n<ul style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; list-style: none; clear: both; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; background: rgb(255, 255, 255);\">\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; line-height: 1.9; list-style-position: outside; background: transparent;\"><span style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 255); background: transparent;\">&nbsp; &nbsp; &nbsp;&nbsp;- C&oacute; c&aacute;i nh&igrave;n r&otilde; r&agrave;ng v&agrave; tổng thể hơn về hiện trạng ti&ecirc;u thụ, sử dụng năng lượng trong hệ thống</span></li>\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; line-height: 1.9; list-style-position: outside; background: transparent;\"><span style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 255); background: transparent;\">&nbsp; &nbsp; &nbsp; - C&oacute; được những giải ph&aacute;p sử dụng năng lượng hiệu quả c&ugrave;ng với c&aacute;c b&aacute;o c&aacute;o về t&iacute;nh khả thi của từng giải ph&aacute;p</span></li>\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; line-height: 1.9; list-style-position: outside; background: transparent;\"><span style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 255); background: transparent;\">&nbsp; &nbsp; &nbsp; - Dễ d&agrave;ng lập kế hoạch thực hiện c&aacute;c giải ph&aacute;p sử dụng năng lượng hiệu quả cho c&aacute;c đối tượng v&agrave; khu vực ưu ti&ecirc;n</span></li>\n</ul>\n\n<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; background: rgb(255, 255, 255);\">&nbsp; &nbsp; &nbsp; &nbsp; Giảm chi ph&iacute; sử dụng năng lượng cũng ch&iacute;nh l&agrave; n&acirc;ng cao hiệu quả sản xuất kinh doanh v&agrave; g&oacute;p phần bảo vệ m&ocirc;i trường</p>\n\n<p style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; background: rgb(255, 255, 255);\">&nbsp; &nbsp; &nbsp; &nbsp; Quy tr&igrave;nh thực hiện tiết kiệm năng lượng:</p>\n\n<ul style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; font-size: 13px; vertical-align: baseline; list-style: none; clear: both; font-family: Arial, Helvetica, sans-serif; line-height: 24.7000007629395px; background: rgb(255, 255, 255);\">\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; line-height: 1.9; list-style-position: outside; background: transparent;\"><span style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 255); background: transparent;\">&nbsp; &nbsp; &nbsp; 1. Đo đạc</span></li>\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; line-height: 1.9; list-style-position: outside; background: transparent;\"><span style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 255); background: transparent;\">&nbsp; &nbsp; &nbsp; 2. Tổ chức cơ bản</span></li>\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; line-height: 1.9; list-style-position: outside; background: transparent;\"><span style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 255); background: transparent;\">&nbsp; &nbsp; &nbsp; 3. Tự động h&oacute;a</span></li>\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; line-height: 1.9; list-style-position: outside; background: transparent;\"><span style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 255); background: transparent;\">&nbsp; &nbsp; &nbsp; 4. Gi&aacute;m s&aacute;t v&agrave; cải tiến</span></li>\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; line-height: 1.9; list-style-position: outside; background: transparent;\">&nbsp;</li>\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; line-height: 1.9; list-style-position: outside; text-align: center; background: transparent;\">&nbsp;</li>\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; line-height: 1.9; list-style-position: outside; text-align: center; background: transparent;\">&nbsp;</li>\n <li style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; line-height: 1.9; list-style-position: outside; text-align: center; background: transparent;\"><img alt=\"Tiet kiem nang luong 2\" height=\"296\" src=\"https://www.dasautomation.vn/images/images/Tiet_kiem_nang_luong_2.jpg\" style=\"margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\" width=\"500\" /></li>\n</ul>\n', '', 'Tiet_kiem_nang_luong_1_20150515055206.jpg.webp', '', '', 1, 0, '', 748, 1, '2015-01-08', '2015-05-15', NULL, NULL, NULL),
