(523, 6, 55, 'tu-van-thiet-ke-he-thong-dien', 'Tư vấn thiết kế hệ thống điện,', '', '', NULL, '0', '0', '', '<p>Tư vấn thiết kế hệ thống điện,</p>\n', '<p>Tư vấn thiết kế hệ thống điện,</p>\n', '', '', '', '', 0, 0, '', 1, 1, '2015-05-15', '2015-05-15', NULL, NULL, NULL),
(524, 6, 5, 'bao-tri-he-thong-dien', 'Bảo trì hệ thống điện, tủ bảng điện', '', '', NULL, '0', '0', '', '<p>Vivamus sed aliquet lectus. Vivamus non lectus justo. Sed accumsan mauris erat, elementum dapibus massa convallis vitae</p>\n', '<p style=\"line-height: 20.7999992370605px;\"><em style=\"line-height: 1.6em; color: rgb(102, 51, 255);\"><strong>Bảo tr&igrave; tủ điện hạ thế:</strong></em></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"font-size: 14px;\">- Scan nhiệt đầu c&aacute;p, busbar trước v&agrave; sau khi bảo tr&igrave;.</span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"font-size: 14px;\">- Kiểm tra tổng qu&aacute;t tất cả c&aacute;c thiết bị trước v&agrave; sau tủ.</span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"font-size: 14px;\">- L&agrave;m sạch bằng m&aacute;y h&uacute;t bụi v&agrave; dung dịch chuy&ecirc;n dụng.</span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"font-size: 14px;\">- Siết chặt c&aacute;c đầu nối c&aacute;p, busbar, thanh dẫn.</span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"font-size: 14px;\">- Kiểm tra c&aacute;ch điện thanh busbar, ph&aacute;t hiện vị tr&iacute; c&aacute;ch điện thấp.</span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"font-size: 14px;\">- Kiểm tra thiết bị đ&oacute;ng ngắt, phần c&aacute;ch điện v&agrave; kh&oacute;a li&ecirc;n động.</span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"font-size: 14px;\">- Kiểm tra th&ocirc;ng mạch cầu ch&igrave;, đ&egrave;n b&aacute;o, n&uacute;t nhấn.</span></p>\n\n<p style=\"line-height: 20.7999992370605px;\"><span style=\"color: rgb(102, 0, 255);\"><strong><em>Bảo tr&igrave; ACB, MCCB&nbsp;</em></strong></span>:</p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"font-size: 14px;\">&nbsp;Scan nhiệt đầu cực ACB, MCCB trước v&agrave; sau khi bảo tr&igrave;.</span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"font-size: 14px;\">- Kiểm tra tổng qu&aacute;t, l&agrave;m sạch bằng m&aacute;y h&uacute;t bụi v&agrave; dung dịch chuy&ecirc;n dụng.</span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"font-size: 14px;\">- Kiểm tra chức năng đ&oacute;ng cắt cơ, điện</span><span style=\"font-size: 14px;\">.</span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"font-size: 14px;\">- Đo điện trở tiếp x&uacute;c v&agrave; điện trở c&aacute;ch điện ở c&aacute;c cực m&aacute;y cắt bằng thiết bị&nbsp;chuy&ecirc;n dụng.</span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"font-size: 14px;\">- Kiểm tra kh&oacute;a an to&agrave;n, đảm bảo vận h&agrave;nh ch&iacute;nh x&aacute;c.</span></p>\n\n<p style=\"line-height: 20.7999992370605px;\"><span style=\"color: rgb(102, 51, 255);\"><em><strong>Hệ thống tụ b&ugrave;:</strong></em></span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"font-size: 14px;\">- Kiểm tra tổng qu&aacute;t, l&agrave;m sạch c&aacute;c khối tụ bằng m&aacute;y h&uacute;t bụi v&agrave; dung dịch chuy&ecirc;n&nbsp;dụng.</span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"font-size: 14px;\">- Kiểm tra nhiệt độ b&ecirc;n ngo&agrave;i v&agrave; b&ecirc;n trong tủ.</span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"font-size: 14px;\">- Đo gi&aacute; trị điện dung tụ b&ugrave;.</span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"font-size: 14px;\">- Kiểm tra hoạt động của c&aacute;c contactor, MCCB điều khiển tụ b&ugrave;.</span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"font-size: 14px;\">- L&agrave;m sạch c&aacute;p v&agrave; siết chặt c&aacute;c đầu nối c&aacute;p.</span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\">&nbsp;</p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"color: rgb(102, 153, 255);\"><em style=\"color: rgb(0, 1, 4); font-size: 14px; text-align: justify;\">Sau khi bảo tr&igrave; hệ thống, ngo&agrave;i n</em></span><span style=\"color:#005491;\"><em style=\"color: rgb(0, 1, 4); font-size: 14px; text-align: justify;\">hững</em></span><span style=\"color: rgb(102, 153, 255);\"><em style=\"color: rgb(0, 1, 4); font-size: 14px; text-align: justify;\"> vấn đề đ&atilde; xử l&yacute; trong qu&aacute; tr&igrave;nh bảo tr&igrave;, ch&uacute;ng t&ocirc;i c&ograve;n c&oacute; bản b&aacute;o c&aacute;o, b&aacute;o c&aacute;o về thực trạng hệ thống cũng như những khuyến c&aacute;o nhằm n&acirc;ng cao chất lượng hệ thống v&agrave; an to&agrave;n cho người vận h&agrave;nh.</em></span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\">&nbsp;</p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><span style=\"color: rgb(102, 153, 255);\"><em style=\"color: rgb(0, 1, 4); font-size: 14px; text-align: justify;\"><img alt=\"\" src=\"/fileman/Uploads/ScreenHunter_95 Dec_ 01 21_16.jpg\" style=\"width: 230px; height: 161px;\" />&nbsp; &nbsp; &nbsp;&nbsp;<img alt=\"\" src=\"/fileman/Uploads/ScreenHunter_103 Dec_ 01 21_38.jpg\" style=\"width: 230px; height: 161px;\" /></em></span></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><em>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Bảo tr&igrave; tủ điện hạ thế &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; </em><em style=\"color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\">Bảo tr&igrave; m&aacute;y cắt ACB</em></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\">&nbsp;</p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><em style=\"color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\"><img alt=\"\" src=\"/fileman/Uploads/ScreenHunter_96 Dec_ 01 21_16.jpg\" style=\"width: 230px; height: 150px;\" />&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<img alt=\"\" src=\"/fileman/Uploads/ScreenHunter_97 Dec_ 01 21_16.jpg\" style=\"width: 230px; height: 150px;\" /></em></p>\n\n<p style=\"padding: 0px; margin: 0px; color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Scan nhiệt độ của MCCB &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<em style=\"color: rgb(0, 1, 4); font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 18px;\">Bảo tr&igrave; hệ thống tụ b&ugrave;&nbsp;</em></p>\n', '', 'sv_20200818110928.jpg.webp', '', '', 0, 0, '', 1, 1, '2015-05-15', '2020-08-18', NULL, NULL, NULL),
(525, 6, 5, 'bao-tri-he-thong-dieu-hoa-khong-khi-va-thong-gio', 'Bảo trì hệ thống điều hòa không khí và thông gió', '', '', NULL, '0', '0', '', '<p>Vivamus sed aliquet lectus. Vivamus non lectus justo. Sed accumsan mauris erat, elementum dapibus massa convallis vitae</p>\n', '<p><span style=\"color: rgb(0, 0, 0); font-family: calibri, arial, sans, sans-serif; font-size: 14px; line-height: normal; white-space: pre-wrap;\">Bảo tr&igrave; hệ thống điều h&ograve;a kh&ocirc;ng kh&iacute; v&agrave; th&ocirc;ng gi&oacute;</span></p>\n', '', 'sv_20200818110941.jpg.webp', '', '', 0, 0, '', 1, 1, '2015-05-15', '2020-08-18', NULL, NULL, NULL),
(526, 6, 5, 'bao-tri-he-thong-dien-thay-acquy-he-thong-ups', 'Bảo trì hệ thống điện, thay acquy hệ thống UPS', '', '', NULL, '0', '0', '', '', '<p><em><strong>Bảo tr&igrave; tủ điện hạ thế:</strong></em></p>\n\n<p>- Scan nhiệt đầu c&aacute;p, busbar trước v&agrave; sau khi bảo tr&igrave;.</p>\n\n<p>- Kiểm tra tổng qu&aacute;t tất cả c&aacute;c thiết bị trước v&agrave; sau tủ.</p>\n\n<p>- L&agrave;m sạch bằng m&aacute;y h&uacute;t bụi v&agrave; dung dịch chuy&ecirc;n dụng.</p>\n\n<p>- Siết chặt c&aacute;c đầu nối c&aacute;p, busbar, thanh dẫn.</p>\n\n<p>- Kiểm tra c&aacute;ch điện thanh busbar, ph&aacute;t hiện vị tr&iacute; c&aacute;ch điện thấp.</p>\n\n<p>- Kiểm tra thiết bị đ&oacute;ng ngắt, phần c&aacute;ch điện v&agrave; kh&oacute;a li&ecirc;n động.</p>\n\n<p>- Kiểm tra th&ocirc;ng mạch cầu ch&igrave;, đ&egrave;n b&aacute;o, n&uacute;t nhấn.</p>\n\n<p><strong><em>Bảo tr&igrave; ACB, MCCB&nbsp;</em></strong>:</p>\n\n<p>&nbsp;Scan nhiệt đầu cực ACB, MCCB trước v&agrave; sau khi bảo tr&igrave;.</p>\n\n<p>- Kiểm tra tổng qu&aacute;t, l&agrave;m sạch bằng m&aacute;y h&uacute;t bụi v&agrave; dung dịch chuy&ecirc;n dụng.</p>\n\n<p>- Kiểm tra chức năng đ&oacute;ng cắt cơ, điện.</p>\n\n<p>- Đo điện trở tiếp x&uacute;c v&agrave; điện trở c&aacute;ch điện ở c&aacute;c cực m&aacute;y cắt bằng thiết bị&nbsp;chuy&ecirc;n dụng.</p>\n\n<p>- Kiểm tra kh&oacute;a an to&agrave;n, đảm bảo vận h&agrave;nh ch&iacute;nh x&aacute;c.</p>\n\n<p><em><strong>Hệ thống tụ b&ugrave;:</strong></em></p>\n\n<p>- Kiểm tra tổng qu&aacute;t, l&agrave;m sạch c&aacute;c khối tụ bằng m&aacute;y h&uacute;t bụi v&agrave; dung dịch chuy&ecirc;n&nbsp;dụng.</p>\n\n<p>- Kiểm tra nhiệt độ b&ecirc;n ngo&agrave;i v&agrave; b&ecirc;n trong tủ.</p>\n\n<p>- Đo gi&aacute; trị điện dung tụ b&ugrave;.</p>\n\n<p>- Kiểm tra hoạt động của c&aacute;c contactor, MCCB điều khiển tụ b&ugrave;.</p>\n\n<p>- L&agrave;m sạch c&aacute;p v&agrave; siết chặt c&aacute;c đầu nối c&aacute;p.</p>\n\n<p><em>Sau khi bảo tr&igrave; hệ thống, ngo&agrave;i n</em><em>hững</em><em>&nbsp;vấn đề đ&atilde; xử l&yacute; trong qu&aacute; tr&igrave;nh bảo tr&igrave;, ch&uacute;ng t&ocirc;i c&ograve;n c&oacute; bản b&aacute;o c&aacute;o, b&aacute;o c&aacute;o về thực trạng hệ thống cũng như những khuyến c&aacute;o nhằm n&acirc;ng cao chất lượng hệ thống v&agrave; an to&agrave;n cho người vận h&agrave;nh.</em></p>\n\n<div id=\"gallery-index-pro\">\n<div id=\"gallery-masonry-loading\">\n<div class=\"gallery-masonry\">\n<div class=\"gallery-item-pro gallery-column-3\">\n<article>\n<div class=\"zoom-image-container-pro\"><a class=\"gallery-container-pro fancybox\" data-fancybox-group=\"gallery\" href=\"https://toandanhco.com.vn/fileman/Uploads/service/sv4_3.jpg\"><img src=\"https://toandanhco.com.vn/fileman/Uploads/service/sv4_3.jpg\" /></a></div>\n</article>\n</div>\n\n<div class=\"gallery-item-pro gallery-column-3\">\n<article>\n<div class=\"zoom-image-container-pro\"><a class=\"gallery-container-pro fancybox\" data-fancybox-group=\"gallery\" href=\"https://toandanhco.com.vn/fileman/Uploads/service/sv4_4.jpg\"><img src=\"https://toandanhco.com.vn/fileman/Uploads/service/sv4_4.jpg\" /></a></div>\n</article>\n</div>\n\n<div class=\"gallery-item-pro gallery-column-3\">\n<article>\n<div class=\"zoom-image-container-pro\"><a class=\"gallery-container-pro fancybox\" data-fancybox-group=\"gallery\" href=\"https://toandanhco.com.vn/fileman/Uploads/service/sv4_5.jpg\"><img src=\"https://toandanhco.com.vn/fileman/Uploads/service/sv4_5.jpg\" /></a></div>\n</article>\n</div>\n\n<div class=\"gallery-item-pro gallery-column-3\">\n<article>\n<div class=\"zoom-image-container-pro\"><a class=\"gallery-container-pro fancybox\" data-fancybox-group=\"gallery\" href=\"https://toandanhco.com.vn/fileman/Uploads/service/sv4_6.jpg\"><img src=\"https://toandanhco.com.vn/fileman/Uploads/service/sv4_6.jpg\" /></a></div>\n</article>\n</div>\n\n<div class=\"gallery-item-pro gallery-column-3\">\n<article>\n<div class=\"zoom-image-container-pro\"><a class=\"gallery-container-pro fancybox\" data-fancybox-group=\"gallery\" href=\"https://toandanhco.com.vn/fileman/Uploads/service/sv4_1.jpg\"><img src=\"https://toandanhco.com.vn/fileman/Uploads/service/sv4_1.jpg\" /></a></div>\n</article>\n</div>\n\n<div class=\"gallery-item-pro gallery-column-3\">\n<article>\n<div class=\"zoom-image-container-pro\"><a class=\"gallery-container-pro fancybox\" data-fancybox-group=\"gallery\" href=\"https://toandanhco.com.vn/fileman/Uploads/service/sv4_2.jpg\"><img src=\"https://toandanhco.com.vn/fileman/Uploads/service/sv4_2.jpg\" /></a></div>\n</article>\n</div>\n</div>\n</div>\n</div>\n', '', 'sv_20200818111106.jpg.webp', '', '', 0, 1, '3', 1, 1, '2015-05-15', '2021-06-01', '', NULL, NULL),
(527, 6, 55, 'he-thong-tu-bang-dien-ha-the', 'Hệ thống tủ bảng điện hạ thế', '', '', NULL, '0', '0', '', '<p>Chuy&ecirc;n cung cấp&nbsp;tủ bảng điện hạ thế&nbsp;cho Building, nh&agrave; m&aacute;y, c&aacute;c dự &aacute;n&nbsp;y&ecirc;u cầu chất lượng kỹ thuật cao .</p>\n', '<p><span style=\"line-height: 20.7999992370605px;\">Chuy&ecirc;n cung cấp</span><span style=\"line-height: 20.7999992370605px;\">&nbsp;tủ bảng điện hạ thế</span><span style=\"line-height: 20.7999992370605px;\">&nbsp;cho Building, nh&agrave; m&aacute;y, c&aacute;c dự &aacute;n&nbsp;y&ecirc;u cầu chất lượng kỹ thuật cao .</span></p>\n\n<p><span style=\"line-height: 20.7999992370605px;\">-Tủ H&ograve;a Đồng Bộ</span></p>\n\n<p>-Tủ ATS</p>\n\n<p>-Tủ Tụ B&ugrave;</p>\n\n<p>-Tủ Ph&acirc;n Phối</p>\n\n<p>-Tủ Bơm, Tủ MCC</p>\n\n<p>-Tủ DDC trong điều h&ograve;a kh&ocirc;ng kh&iacute;</p>\n\n<p>-Tủ PLC, Tự động h&oacute;a,...</p>\n\n<p>&nbsp;</p>\n\n<p><a class=\"pop_up\" href=\"https://toandanhco.com.vn/fileman/Uploads/IMG_1061.jpg\"><img alt=\"\" src=\"/fileman/Uploads/IMG_1061.jpg\" style=\"width: 200px; height: 150px;\" /></a>&nbsp; &nbsp;&nbsp;<a class=\"pop_up\" href=\"https://toandanhco.com.vn/fileman/Uploads/10644576_629147863869844_6232963190873092792_n.jpg\"><img alt=\"\" src=\"/fileman/Uploads/10644576_629147863869844_6232963190873092792_n.jpg\" style=\"width: 200px; height: 150px;\" /></a></p>\n\n<p><a class=\"pop_up\" href=\"https://toandanhco.com.vn/fileman/Uploads/P1040129.jpg\"><img alt=\"\" src=\"/fileman/Uploads/P1040129.jpg\" style=\"width: 200px; height: 150px;\" /></a>&nbsp; &nbsp;&nbsp;<a class=\"pop_up\" href=\"https://toandanhco.com.vn/fileman/Uploads/IMG_1091.jpg\"><img alt=\"\" src=\"/fileman/Uploads/IMG_1091.jpg\" style=\"width: 200px; height: 150px;\" /></a></p>\n\n<p>&nbsp;</p>\n\n<p><a class=\"pop_up\" href=\"https://toandanhco.com.vn/fileman/Uploads/IMG_1902.jpg\"><img alt=\"\" src=\"/fileman/Uploads/IMG_1902.jpg\" style=\"width: 200px; height: 150px;\" /></a>&nbsp; &nbsp;&n