(137, 23, 75, NULL, 0, 0, 'cong-tac-cam-ung-4-nut-dieu-khien-tu-xa', 'Công tắc cảm ứng 4 nút điều khiển từ xa', '', '', NULL, 0, 0, NULL, '<p>Vivamus sed aliquet lectus. Vivamus non lectus justo. Sed accumsan mauris erat, elementum dapibus massa convallis vitae</p>\n', '', NULL, '', '', '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">C&ocirc;ng tắc cảm ứng 4 n&uacute;t điều khiển từ xa</h1>\n', 'ct5_20150518054010.png.webp', 'resize_ct5_20150518054010.png.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 5, 1, 1, '2020-08-18', '2020-08-18', NULL, '.webp', NULL, NULL),
(138, 23, 75, NULL, 0, 0, 'dieu-khien-tu-xa-tien-ich-lumi', 'Điều khiển từ xa tiện ích Lumi', '', '', NULL, 0, 0, NULL, '<p>Vivamus sed aliquet lectus. Vivamus non lectus justo. Sed accumsan mauris erat, elementum dapibus massa convallis vitae</p>\n', '', NULL, '', '', '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">Điều khiển từ xa tiện &iacute;ch Lumi</h1>\n', 'ct7_20150518054108.png.webp', 'resize_ct7_20150518054108.png.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 9, 1, 1, '2020-08-18', '2020-08-18', NULL, '.webp', NULL, NULL),
